import{at as e,n as t,ot as n,yt as r}from"./chunks/framework.Dkh1x705.js";var i=JSON.parse(`{"title":"Установка","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1795455254000}`),a={name:`guide/index.md`};function o(t,i,a,o,s,c){return r(),e(`div`,null,[...i[0]||=[n(`<h1 id="установка" tabindex="-1">Установка <a class="header-anchor" href="#установка" aria-label="Permalink to “Установка”">​</a></h1><p>Yamapper — расширение для браузера на Manifest V3. Работает в Chrome, Яндекс.Браузере и Firefox.</p><h2 id="установка-из-магазина" tabindex="-1">Установка из магазина <a class="header-anchor" href="#установка-из-магазина" aria-label="Permalink to “Установка из магазина”">​</a></h2><ul><li><strong>Chrome и Яндекс.Браузер</strong> — <a href="https://chromewebstore.google.com/detail/nmapuploader/ohnbeklcgbilmddjahpkmgdlhljgjamd" target="_blank" rel="noreferrer">Chrome Web Store</a> → «Установить».</li><li><strong>Firefox</strong> — <a href="https://addons.mozilla.org/ru/firefox/addon/nmap-uploader/" target="_blank" rel="noreferrer">addons.mozilla.org</a> → «Добавить в Firefox».</li></ul><p>После установки откройте <a href="https://n.maps.yandex.ru/" target="_blank" rel="noreferrer">редактор Народной карты</a>. Если вкладка была открыта заранее — обновите её, иначе кнопки не появятся.</p><h2 id="требования" tabindex="-1">Требования <a class="header-anchor" href="#требования" aria-label="Permalink to “Требования”">​</a></h2><ul><li>Современный браузер с поддержкой Manifest V3 (Chrome 137+, Firefox 140+).</li><li>Аккаунт Яндекс ID — расширение сохраняет файлы на ваш Яндекс Диск.</li><li>Доступ к <code>n.maps.yandex.ru</code>.</li></ul><h2 id="какие-разрешения-запрашиваются" tabindex="-1">Какие разрешения запрашиваются <a class="header-anchor" href="#какие-разрешения-запрашиваются" aria-label="Permalink to “Какие разрешения запрашиваются”">​</a></h2><table tabindex="0"><thead><tr><th>Разрешение</th><th>Зачем</th><th>Когда спрашивается</th></tr></thead><tbody><tr><td><code>storage</code></td><td>настройки и сессия</td><td>при установке</td></tr><tr><td><code>scripting</code>, <code>tabs</code>, <code>activeTab</code></td><td>панель и content scripts на странице редактора</td><td>при установке</td></tr><tr><td><code>n.maps.yandex.ru</code>, <code>nakarte.me</code></td><td>работа на карте и раздельный вид</td><td>при установке</td></tr><tr><td>Яндекс Диск и <code>identity</code></td><td>Блокнот, заметки, загрузка данных</td><td>при включении «Заметок» или первом входе</td></tr><tr><td><code>nspd.gov.ru</code></td><td>загрузка объектов из НСПД</td><td>при включении «Загрузки из НСПД»</td></tr></tbody></table><p>Разрешения Яндекса и НСПД — необязательные: пока функции выключены, расширение к этим доменам не обращается. Выключение функции не отзывает уже выданное разрешение — это делается в настройках браузера.</p><p>Подробнее о том, что расширение читает и пишет, — в разделе <a href="/yamapper/guide/support#privacy">«Приватность»</a> и в README репозитория.</p><h2 id="первые-шаги" tabindex="-1">Первые шаги <a class="header-anchor" href="#первые-шаги" aria-label="Permalink to “Первые шаги”">​</a></h2><ol><li>Откройте редактор и найдите кнопку-шестерёнку в шапке — это настройки.</li><li>Загрузите первый файл по инструкции <a href="/yamapper/guide/first-upload">«Первая загрузка»</a>.</li><li>Пройдитесь по разделам справки: <a href="/yamapper/guide/editor/">Редактор</a>, <a href="/yamapper/guide/moderation/">Модерация</a>, <a href="/yamapper/guide/style/">Стиль</a>.</li></ol><h2 id="если-что-то-не-появилось" tabindex="-1">Если что-то не появилось <a class="header-anchor" href="#если-что-то-не-появилось" aria-label="Permalink to “Если что-то не появилось”">​</a></h2><p>Кнопок нет на карте — смотрите <a href="/yamapper/guide/faq#no-buttons">«Кнопки не появились на карте»</a>. Остальные ошибки — в разделе <a href="/yamapper/guide/faq">«Вопросы и типичные ошибки»</a>.</p>`,15)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};